'use strict';

/**
* BLAS level 1 routine to find the index of the first element having the maximum absolute value.
*
* @module @stdlib/blas/base/izamax
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var izamax = require( '@stdlib/blas/base/izamax' );
*
* var zx = new Complex128Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
*
* var idx = izamax( zx.length, zx, 1 );
* // returns 1
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var izamax = require( '@stdlib/blas/base/izamax' );
*
* var zx = new Complex128Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
*
* var idx = izamax.ndarray( zx.length, zx, 1, 0 );
* // returns 1
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var izamax;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	izamax = main;
} else {
	izamax = tmp;
}


// EXPORTS //

module.exports = izamax;

// exports: { "ndarray": "izamax.ndarray" }
